/**
 * Adsterra configuration.
 *
 * Every `snippet` below is the code generated by the Adsterra dashboard for the site owner's account.
 * Keep it exactly as Adsterra gave it. Do not log or share the keys outside this file.
 *
 * Banner formats (728x90, 468x60, 320x50, 300x250, 160x300/600) are mounted by `AdSlot`, each inside its
 * own iframe, so that Adsterra's global `atOptions` variable cannot collide between slots. A snippet is
 * mounted ONCE per page view. It is never re-injected on Generate clicks. See `AdSlot.tsx` for the frame
 * permissions and why they are what they are.
 *
 * Page-level formats (Social Bar, Popunder, Interstitial) are different: Adsterra's own script decides when
 * they show. They go in index.html (see ADSTERRA_SETUP.md). They cannot be triggered on demand.
 */

export type AdSlotId =
  | 'top-banner'
  | 'mid-banner'
  | 'features-banner'
  | 'faq-banner'
  | 'result-banner'
  | 'page-top-banner'
  | 'page-bottom-banner'
  | 'footer-banner'

export interface AdSlotConfig {
  id: AdSlotId
  /** Human-readable description for dev placeholders and docs. */
  description: string
  /** Fallback size in CSS px, used only if the size cannot be read from the snippet's `atOptions`. */
  width: number
  height: number
  /**
   * Exact HTML snippet from Adsterra (the `atOptions` block plus the invoke script for banners,
   * or the container + script for Native Banner). `null` = not configured.
   */
  snippet: string | null
  /**
   * Optional smaller unit (for example 320x50) used instead of `snippet` when the viewport is narrower than
   * `ADS_CONFIG.desktopMinWidth`. The choice is made once, when the slot mounts. Ad units are never scaled
   * or resized with CSS, because that alters the creative.
   */
  mobileSnippet?: string | null
}

