export const ADS_CONFIG = {
  /** Master switch. false removes every ad slot (and placeholder) from the UI. */
  enabled: true,
  /**
   * Show the "Adsterra integration not configured" placeholder for slots with no snippet.
   * Defaults to development only. Set VITE_SHOW_AD_PLACEHOLDERS=true to force it on in a build.
   */
  showPlaceholders: import.meta.env.DEV || import.meta.env.VITE_SHOW_AD_PLACEHOLDERS === 'true',
  /**
   * What a user-initiated Generate click does for ads:
   *  - 'reveal-result-slot': the first time the user generates, the result banner under the
   *    QR is shown. Its script is mounted once, not once per click.
   *  - 'none': Generate never touches ads.
   */
  generateAction: 'reveal-result-slot' as 'reveal-result-slot' | 'none',
  /**
   * false (default): ad frames run on this site's origin with a restricted sandbox, so Adsterra sees the
   * real page URL (Referer) and its code can use cookies and storage. This is how a pasted banner would behave
   * in the page itself. Third-party code in the frame can technically read this site's browser storage.
   * true: fully isolated (opaque-origin) frames. Safer for the app's data, but the ad request carries no
   * Referer and the ad code cannot use storage or cookies, which prevented ads from being served. See ADSTERRA_SETUP.md.
   */
  isolateFrames: false,
  /** Viewports at least this wide (CSS px) get `snippet`; narrower ones get `mobileSnippet` if set. */
  desktopMinWidth: 760,
}

export interface UnitSize {
  width: number
  height: number
}

/** Reads the unit size from a banner snippet's `atOptions` block. Returns null if it is not present. */
export function parseUnitSize(snippet: string): UnitSize | null {
  const w = /['"]?width['"]?\s*:\s*(\d+)/.exec(snippet)
  const h = /['"]?height['"]?\s*:\s*(\d+)/.exec(snippet)
  return w && h ? { width: Number(w[1]), height: Number(h[1]) } : null
}

export interface ResolvedUnit extends UnitSize {
  snippet: string
  variant: 'default' | 'mobile'
}

/**
 * Chooses the unit for a slot at the given viewport width, or null when the slot has no real code.
 * The size comes from the snippet itself so the reserved space always matches the ad.
 */
export function resolveAdUnit(id: AdSlotId, viewportWidth: number): ResolvedUnit | null {
  const cfg = AD_SLOTS[id]
  const useMobile = Boolean(cfg.mobileSnippet?.trim()) && viewportWidth < ADS_CONFIG.desktopMinWidth
  const snippet = useMobile ? cfg.mobileSnippet : cfg.snippet
  if (!snippet || !snippet.trim()) return null
  const size = parseUnitSize(snippet) ?? { width: cfg.width, height: cfg.height }
  return { snippet, ...size, variant: useMobile ? 'mobile' : 'default' }
}

/** True when a slot has real owner-supplied code. */
export function isSlotConfigured(id: AdSlotId): boolean {
  const s = AD_SLOTS[id].snippet
  return Boolean(s && s.trim())
}
